import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"HKDF","description":"","frontmatter":{"title":"HKDF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hkdf.md","filePath":"cs/hkdf.md","lastUpdated":1789023840000}'),p={name:"cs/hkdf.md"};function E(f,a,K,D,_,m){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="hkdf" tabindex="-1">HKDF <a class="header-anchor" href="#hkdf" aria-label="Permalink to &quot;HKDF&quot;">​</a></h1><div class="epigraph"><p>HKDF 先用 HMAC 提取，把不匀的输入密钥材料收成伪随机密钥，再扩展出多条用途分离的输出。它不是慢哈希，也不从弱口令里变出熵。</p><footer>—— Krawczyk, Cryptographic Extraction and Key Derivation, 2010；RFC 5869</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/csprng">CSPRNG</a>从熵池抽新鲜随机。缺口是<strong>已经有共享秘密</strong>（ECDH 输出、PSK）时如何派生 AEAD 键、IV 盐、下一跳棘轮键。主干<a href="/cs/kdf-slow-hash">KDF 与慢哈希</a>管口令；本课 HKDF 管高熵 IKM。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ECDH 的共享坐标不是均匀密钥。直接截断当 AES 键会留结构。HKDF-Extract(salt, IKM)→PRK，HKDF-Expand(PRK, info, L)→OKM。<code>info</code> 做域分离：同一 IKM 不能在两条协议里撞键。缺口是提取–扩展，不是再讲 bcrypt。</p><h3 id="不能当口令哈希" tabindex="-1">不能当口令哈希 <a class="header-anchor" href="#不能当口令哈希" aria-label="Permalink to &quot;不能当口令哈希&quot;">​</a></h3><p>口令熵低，要慢哈希与盐。HKDF 快，假设 IKM 已有足够熵。</p><p><span class="marginnote">RFC 5869。TLS 1.3 的 HKDF-Expand-Label 是加了标签的扩展。Signal 棘轮更后用同一思想。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 Extract 与 Expand。强调 salt 与 info 的角色。对照：ChaCha/AES 的密钥从 OKM 切开，nonce 另计。指出长度扩展已由 HMAC 关。</p>',12)),(e(),s(c,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IKM%5B%22ECDH%20%E7%AD%89%20IKM%22%5D%20--%3E%20EX%5B%22HKDF-Extract%22%5D%0A%20%20SALT%5B%22%E7%9B%90%22%5D%20--%3E%20EX%0A%20%20EX%20--%3E%20PRK%5B%22PRK%22%5D%0A%20%20PRK%20--%3E%20EXP%5B%22HKDF-Expand%20%2B%20info%22%5D%0A%20%20EXP%20--%3E%20OKM%5B%22%E7%94%A8%E9%80%94%E5%88%86%E7%A6%BB%E7%9A%84%E9%94%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>域分离让「同一共享秘密」长出握手密钥、应用密钥、导出密钥而不串用。这是协议级构造的零件。密钥如何存放、谁能碰，下一课 HSM 与生命周期——算法再对，内存里的明文键仍是威胁模型里的端点。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Argon2 重写一遍。原语课序到 HKDF 收口；下一课序协议级构造从密钥管理与 HSM 起，问「键在哪」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CSPRNG 产熵；HKDF 从已有 IKM 提取并扩展。</li><li>info 做域分离；不能当慢口令哈希。</li><li>TLS 1.3 与棘轮都吃 HKDF。</li><li>下一课序：密钥管理与 HSM。</li><li>出处：Krawczyk, 2010；RFC 5869；对照 RFC 8446。</li></ul>',8))])}const P=i(p,[["render",E]]);export{A as __pageData,P as default};
